<script>
document.addEventListener('DOMContentLoaded',()=>{
 const chartText='#52657b',grid='rgba(80,105,130,.13)';
 const catLabels=<?=json_encode(array_column($cats,'name'),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
 const catValues=<?=json_encode(array_map('intval',array_column($cats,'qty')) )?>;
 const categoryCanvas=document.getElementById('categoryChart');
 if(categoryCanvas){new Chart(categoryCanvas,{type:'doughnut',data:{labels:catLabels,datasets:[{data:catValues,backgroundColor:['#1769d2','#16a085','#f4a62a','#8b5cf6','#e15b64','#0ea5e9','#64748b','#84cc16'],borderWidth:2,borderColor:'#fff'}]},options:{responsive:true,maintainAspectRatio:false,cutout:'65%',plugins:{legend:{position:'bottom',labels:{color:chartText,boxWidth:10,padding:14}}}}});}
 const months=<?=json_encode($months,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
 const movementCanvas=document.getElementById('movementChart');
 if(movementCanvas){new Chart(movementCanvas,{type:'bar',data:{labels:months.map(x=>x.m),datasets:[{label:'Stock In',data:months.map(x=>Number(x.stock_in)),backgroundColor:'#16a085',borderRadius:5},{label:'Stock Out',data:months.map(x=>Number(x.stock_out)),backgroundColor:'#f4a62a',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,scales:{x:{ticks:{color:chartText},grid:{display:false}},y:{beginAtZero:true,ticks:{color:chartText},grid:{color:grid}}},plugins:{legend:{position:'bottom',labels:{color:chartText,boxWidth:10,padding:16}}}}});}
});
</script>
